<body>

<div class="container">
    <h1>Vienna Forge Quick Cards Setup</h1>
    <label for="card1">Card 1:</label>
    <input type="text" id="card1" placeholder="Enter card value or name" />

    <label for="card2">Card 2:</label>
    <input type="text" id="card2" placeholder="Enter card value or name" />

    <label for="card3">Card 3:</label>
    <input type="text" id="card3" placeholder="Enter card value or name" />

    <button onclick="submitCards()">Submit Cards</button>
</div>

<script>
function submitCards() {
    const card1 = document.getElementById('card1').value.trim();
    const card2 = document.getElementById('card2').value.trim();
    const card3 = document.getElementById('card3').value.trim();

    const cardsArray = [card1, card2, card3];

    // Find the first duplicate card
    let duplicateIndex = -1;
    for (let i = 0; i < cardsArray.length; i++) {
        if (cardsArray[i] !== cardsArray[0]) {
            if (cardsArray.indexOf(cardsArray[i]) !== -1) {
                duplicateIndex = i;
                break;
            }
        }
    }

    if (duplicateIndex !== -1) {
        alert(`Duplicate found at index ${duplicateIndex}! Please remove the duplicate before submitting.`);
    } else {
        alert('All cards submitted successfully!');
        // You can add code here to save the cards or perform additional actions
    }
}
</script>

</body>
