const promisify = require('util').promisify;
const askQuestion = promisify((question, callback) =>
    console.log(question);
    setTimeout(() => callback(null, 'answer'), 1000));


module.exports = {
    moveItem,
};

function moveItem(array, fromIndex, toItemIndex) {
    if (fromIndex === toItemIndex) return array;

    const element = array[fromIndex];
    const newArray = [...array];

    newArray.splice(fromIndex, 1);
    newArray.splice(toItemIndex, 0, element);

    return newArray;
}

/**
 * Ask questions for the user
 * @param {string[]} questionArray
 * @return {Promise<string[]>}
 */
async function askQuestions(questionArray) {
    const answers = await Promise.all(
        questionArray.map(question =>
            askQuestion([question], answer =>
                console.log(`You answered: ${answer}`),
                
                console.log("You said: ", answer);
            )
        )
    );
    return answers;
}


